-- =====================================================================
-- Qualification match schedule for The Highlander Summit Signature Event.
-- Run AFTER schema.sql (which creates the matches table) and seed.sql.
-- Safe to re-run: re-importing replaces each match's alliances.
-- Source: Tournament Manager match export (202 qualification matches).
-- =====================================================================

-- make the app offer Q1..Q202 in the match dropdown
update public.events set quals = 202
  where id = '11111111-1111-4111-8111-111111111111';

on conflict (event_id, num) do update set
  red = excluded.red, blue = excluded.blue, field = excluded.field, scheduled = excluded.scheduled;
